 WHERE f.source = 'usda' AND f.source_ref = x.source_ref;
DO $do$
DECLARE
  d jsonb := $rt$[{"name":"قالب عالي الألياف","notes":"وجبات عالية بالألياف (بقوليات، شوفان، حبوب كاملة، خضار وفواكه ومكسرات). زيدي الألياف تدريجياً مع شرب ماء كافي. الأرقام محسوبة من مكونات كل وصفة بقاعدة بيانات USDA. المجموع تقريباً 1855 سعرة (بروتين 110غ، كارب 217غ، دهون 61غ، ألياف 49غ).","meals":[{"kind":"breakfast","title":"شوفان بالشيا والتفاح والجوز","method":"المكونات:\n• 50غ شوفان\n• 200غ حليب قليل الدسم\n• 12غ بذور الشيا (ملعقة كبيرة)\n• 100غ تفاح مقطّع\n• 10غ جوز (عين الجمل)\n• رشة قرفة\n\nالطريقة:\n1. بقدر صغير نسخّن الحليب ونضيف الشوفان والشيا.\n2. نطبخه على نار هادية 5 دقايق مع التحريك لين يثقل.\n3. نسكبه بوعاء ونضيف التفاح المقطّع والجوز ورشة القرفة.\n\nالألياف: 12.2غ\n\nملاحظة: القيم (والألياف) محسوبة من المكونات بقاعدة بيانات USDA. الأعشاب والتوابل والليمون غير محسوبة.","items":[{"food":"شوفان بالشيا والتفاح والجوز","portion":"وجبة كاملة","protein":17.2,"carbs":64.1,"fat":15.7}]},{"kind":"lunch","title":"تشيلي فاصوليا حمراء باللحم","method":"المكونات:\n• 150غ فاصوليا حمراء مطبوخة\n• 100غ لحم بقري مفروم 90% (وزنه بعد الطبخ)\n• 150غ طماطم مفرومة\n• 50غ بصل\n• 60غ فلفل رومي أحمر\n• 100غ رز بني مطبوخ\n• كمون وبابريكا وفلفل حار وثوم وملح\n\nالطريقة:\n1. بقدر نحمّر اللحم المفروم مع البصل والثوم لين يستوي (بدون زيت إضافي).\n2. نضيف الفلفل والطماطم والبهارات ونقلّب دقيقتين.\n3. نضيف الفاصوليا ونص كوب ماء، ونتركه على نار هادية 15 دقيقة لين يتكاثف.\n4. نقدّمه مع الرز البني.\n\nالألياف: 15.1غ\n\nملاحظة: القيم (والألياف) محسوبة من المكونات بقاعدة بيانات USDA. الأعشاب والتوابل والليمون غير محسوبة.","items":[{"food":"تشيلي فاصوليا حمراء باللحم","portion":"وجبة كاملة","protein":44.4,"carbs":73.9,"fat":14.1}]},{"kind":"dinner","title":"سلمون مع عدس وبروكلي","method":"المكونات:\n• 120غ سلمون (وزنه بعد الطبخ)\n• 150غ عدس مطبوخ\n• 120غ بروكلي\n• 1 ملعقة صغيرة زيت زيتون (5غ)\n• ليمون وثوم وملح وفلفل\n\nالطريقة:\n1. نتبّل السلمون بالملح والفلفل والليمون ونشويه بالفرن 15–20 دقيقة.\n2. نطبخ البروكلي على البخار 5 دقايق.\n3. نسخّن العدس بمقلاة مع زيت الزيتون والثوم والملح.\n4. نقدّم السلمون فوق العدس مع البروكلي.\n\nالألياف: 15.8غ\n\nملاحظة: القيم (والألياف) محسوبة من المكونات بقاعدة بيانات USDA. الأعشاب والتوابل والليمون غير محسوبة.","items":[{"food":"سلمون مع عدس وبروكلي","portion":"وجبة كاملة","protein":42.9,"carbs":38.8,"fat":21}]},{"kind":"snack","title":"تمر ولوز","method":"المكونات:\n• حبتين تمر مجدول (48غ)\n• 20غ لوز\n\nالطريقة:\n1. نقدّم التمر مع اللوز، وممكن نحشي كل تمرة بحبات اللوز.\n\nالألياف: 5.7غ\n\nملاحظة: القيم (والألياف) محسوبة من المكونات بقاعدة بيانات USDA. الأعشاب والتوابل والليمون غير محسوبة.","items":[{"food":"تمر ولوز","portion":"طبق","protein":5.1,"carbs":40.3,"fat":10.1}]}]}]$rt$::jsonb;
  p jsonb; m jsonb; it jsonb;
  v_plan uuid; v_meal uuid; i int; j int; k int;
BEGIN
  i := 100 + (SELECT count(*) FROM nutrition_plans WHERE order_id IS NULL);
  FOR p IN SELECT * FROM jsonb_array_elements(d) LOOP
    SELECT id INTO v_plan FROM nutrition_plans WHERE order_id IS NULL AND lower(trim(name)) = lower(trim(p->>'name'));
    IF v_plan IS NULL THEN
      INSERT INTO nutrition_plans (name, notes, position) VALUES (p->>'name', p->>'notes', i) RETURNING id INTO v_plan;
    ELSE
      -- تحديث: الوجبات تُستبدل بالنسخة الحالية (الحذف يشمل عناصرها)
      DELETE FROM plan_meals WHERE plan_id = v_plan;
      UPDATE nutrition_plans SET notes = p->>'notes', updated_at = now() WHERE id = v_plan;
    END IF;
    i := i + 1; j := 0;
    FOR m IN SELECT * FROM jsonb_array_elements(p->'meals') LOOP
      INSERT INTO plan_meals (plan_id, kind, title, method, position) VALUES (v_plan, m->>'kind', m->>'title', nullif(m->>'method', ''), j) RETURNING id INTO v_meal;
      k := 0;
      FOR it IN SELECT * FROM jsonb_array_elements(m->'items') LOOP
        INSERT INTO plan_items (meal_id, food, portion, protein, carbs, fat, position)
        VALUES (v_meal, it->>'food', nullif(it->>'portion', ''), (it->>'protein')::numeric, (it->>'carbs')::numeric, (it->>'fat')::numeric, k);
        k := k + 1;
      END LOOP;
      j := j + 1;
    END LOOP;
  END LOOP;
END $do$;

SELECT p.name, round(sum(i.protein*4 + i.carbs*4 + i.fat*9)) AS kcal, count(DISTINCT m.id) AS meals
  FROM nutrition_plans p JOIN plan_meals m ON m.plan_id = p.id JOIN plan_items i ON i.meal_id = m.id
 WHERE p.order_id IS NULL AND p.name IN ('قالب عالي الألياف') GROUP BY p.name, p.position ORDER BY p.position;
COMMIT;
